#!/usr/bin/env python3
"""Generates the tiny Matroska fixtures in this directory.

The writer here emits real EBML/Matroska structure (the same structure the
reader in `crates/mkv/src/file.rs` parses):

- `sample.mkv`: an EBML header, a segment with a SeekHead, SegmentInfo,
  Tracks (one video, two audio, one subtitle), Chapters ("Opening",
  "Ending") and a font attachment, then a Cluster.
- `no_seekhead.mkv`: an EBML header, a segment with SegmentInfo, Tracks and
  Chapters, then a Cluster. The reader stops at the Cluster.
- `seekhead_gaps.mkv`: an EBML header, a segment with a SeekHead pointing at
  SegmentInfo/Tracks/Chapters, then a dummy Cluster and the elements the
  SeekHead points at. The reader follows the SeekHead past the Cluster.

mkvmerge was not available when these were made; they are generated by this
script instead, so they can be re-created.
"""

from pathlib import Path

OUT = Path(__file__).parent


def vint(value: int) -> bytes:
    """EBML VINT, minimal length, per the reader's `read_vint`."""
    for length in range(1, 9):
        if value < (1 << (7 * length)):
            break
    if length == 8:
        return b"\x01" + value.to_bytes(7, "big")
    marker = 1 << (8 - length)
    shift = 8 * (length - 1)
    first = marker | ((value >> shift) & (marker - 1))
    rest = value & ((1 << shift) - 1)
    out = bytes([first])
    if length > 1:
        out += rest.to_bytes(length - 1, "big")
    return out


def id_bytes(element_id: int) -> bytes:
    """EBML IDs keep their length marker; a 1-byte ID is one byte on disk."""
    if element_id <= 0xFF:
        return bytes([element_id])
    if element_id <= 0xFFFF:
        return element_id.to_bytes(2, "big")
    if element_id <= 0xFFFFFF:
        return element_id.to_bytes(3, "big")
    return element_id.to_bytes(4, "big")


def elem(element_id: int, data: bytes) -> bytes:
    return id_bytes(element_id) + vint(len(data)) + data


def uelem(element_id: int, value: int) -> bytes:
    # EBML unsigned integers are plain big-endian bytes (the size is the
    # element length); the reader reads them with `Element::uint`.
    length = max(1, (value.bit_length() + 7) // 8)
    return elem(element_id, value.to_bytes(length, "big"))


def str_elem(element_id: int, text: str) -> bytes:
    return elem(element_id, text.encode("utf-8"))


def f64_elem(element_id: int, value: float) -> bytes:
    import struct

    return elem(element_id, struct.pack(">d", value))


# Element IDs, per `crates/mkv/src/file.rs`.
ID_EBML_HEADER = 0x1A45DFA3
ID_EBML_VERSION = 0x4286
ID_EBML_DOC_TYPE = 0x4282
ID_EBML_DOC_TYPE_VERSION = 0x4287
ID_SEGMENT = 0x18538067
ID_SEEK_HEAD = 0x114D9B74
ID_SEEK = 0x4DBB
ID_SEEK_ID = 0x53AB
ID_SEEK_POS = 0x53AC
ID_SEGMENT_INFO = 0x1549A966
ID_TIMESTAMP_SCALE = 0x2AD7B1
ID_DURATION = 0x4489
ID_TITLE = 0x7BA9
ID_TRACKS = 0x1654AE6B
ID_TRACK_ENTRY = 0xAE
ID_TRACK_NUM = 0xD7
ID_TRACK_TYPE = 0x83
ID_TRACK_NAME = 0x536E
ID_TRACK_LANGUAGE = 0x22B59C
ID_TRACK_CODEC_ID = 0x86
ID_TRACK_FLAG_DEFAULT = 0x88
ID_TRACK_FLAG_FORCED = 0x55AA
ID_CLUSTER = 0x1F43B675
ID_CHAPTERS = 0x1043A770
ID_EDITION_ENTRY = 0x45B9
ID_EDITION_UID = 0x45BC
ID_EDITION_FLAG_HIDDEN = 0x45BD
ID_EDITION_FLAG_ORDERED = 0x45DD
ID_CHAPTER_ATOM = 0xB6
ID_CHAPTER_UID = 0x73C4
ID_CHAPTER_TIME_START = 0x91
ID_CHAPTER_TIME_END = 0x92
ID_CHAPTER_DISPLAY = 0x80
ID_CHAPTER_STRING = 0x85
ID_CHAPTER_LANGUAGE = 0x437C
ID_ATTACHMENTS = 0x1941A469
ID_ATTACHED_FILE = 0x61A7
ID_FILE_NAME = 0x466E
ID_FILE_MIME_TYPE = 0x4660
ID_FILE_DATA = 0x465C

DURATION_UNITS = 240_000  # at a 1_000_000 ns scale, a 240 s segment


def header() -> bytes:
    return elem(
        ID_EBML_HEADER,
        uelem(ID_EBML_VERSION, 1)
        + str_elem(ID_EBML_DOC_TYPE, "matroska")
        + uelem(ID_EBML_DOC_TYPE_VERSION, 2),
    )


def segment_info() -> bytes:
    return elem(
        ID_SEGMENT_INFO,
        uelem(ID_TIMESTAMP_SCALE, 1_000_000) + f64_elem(ID_DURATION, float(DURATION_UNITS)),
    )


def video_track() -> bytes:
    return elem(
        ID_TRACK_ENTRY,
        uelem(ID_TRACK_NUM, 1)
        + uelem(ID_TRACK_TYPE, 1)
        + str_elem(ID_TRACK_NAME, "Main Video")
        + str_elem(ID_TRACK_CODEC_ID, "V_MPEG4/ISO/AVC")
        + uelem(ID_TRACK_FLAG_DEFAULT, 1),
    )


def audio_track(number: int, name: str, codec: str) -> bytes:
    return elem(
        ID_TRACK_ENTRY,
        uelem(ID_TRACK_NUM, number)
        + uelem(ID_TRACK_TYPE, 2)
        + str_elem(ID_TRACK_NAME, name)
        + str_elem(ID_TRACK_CODEC_ID, codec)
        + uelem(ID_TRACK_FLAG_DEFAULT, 0),
    )


def subtitle_track() -> bytes:
    return elem(
        ID_TRACK_ENTRY,
        uelem(ID_TRACK_NUM, 4)
        + uelem(ID_TRACK_TYPE, 17)
        + str_elem(ID_TRACK_NAME, "English Signs")
        + str_elem(ID_TRACK_LANGUAGE, "eng")
        + str_elem(ID_TRACK_CODEC_ID, "S_TEXT/ASS"),
    )


def tracks() -> bytes:
    return elem(
        ID_TRACKS,
        video_track()
        + audio_track(2, "English", "A_AAC/LC")
        + audio_track(3, "Japanese", "A_AC3")
        + subtitle_track(),
    )


def chapter_atom(name: str, start: int) -> bytes:
    return elem(
        ID_CHAPTER_ATOM,
        uelem(ID_CHAPTER_TIME_START, start)
        + elem(
            ID_CHAPTER_DISPLAY,
            str_elem(ID_CHAPTER_STRING, name) + str_elem(ID_CHAPTER_LANGUAGE, "eng"),
        ),
    )


def chapters() -> bytes:
    return elem(
        ID_CHAPTERS,
        elem(
            ID_EDITION_ENTRY,
            uelem(ID_EDITION_FLAG_ORDERED, 0)
            + chapter_atom("Opening", 0)
            + chapter_atom("Ending", 120_000_000_000),
        ),
    )


def attachment() -> bytes:
    # A font: the TrueType magic number (0x00010000) leads the data.
    font = bytes([0x00, 0x01, 0x00, 0x00]) + b"Sample font data, named with spaces"
    return elem(
        ID_ATTACHMENTS,
        elem(
            ID_ATTACHED_FILE,
            str_elem(ID_FILE_NAME, "Sample Font.ttf")
            + str_elem(ID_FILE_MIME_TYPE, "font/ttf")
            + elem(ID_FILE_DATA, font),
        ),
    )


def cluster() -> bytes:
    # A minimal Cluster: a Timestamp and one SimpleBlock (track 1, timecode 0).
    block = elem(0xA3, bytes([0x81, 0x00, 0x00, 0x00, 0x80, 0x00]))
    return elem(ID_CLUSTER, uelem(0xE7, 0) + block)


def sample_mkv() -> bytes:
    """header + segment(seekhead + info + tracks + chapters + attachment + cluster)."""
    body = chapters() + attachment()
    # The SeekHead targets Chapters, after seekhead + info + tracks. Positions
    # are segment-relative; iterate until the length stops changing.
    target = 0
    for _ in range(4):
        seek_head = _seek_head(ID_CHAPTERS, target)
        next_target = len(seek_head) + len(segment_info()) + len(tracks())
        if next_target == target:
            break
        target = next_target
    seek_head = _seek_head(ID_CHAPTERS, target)
    segment = elem(ID_SEGMENT, seek_head + segment_info() + tracks() + body + cluster())
    return header() + segment


def _seek_head(element_id: int, target_pos: int) -> bytes:
    return elem(
        ID_SEEK_HEAD,
        elem(ID_SEEK, elem(ID_SEEK_ID, element_id.to_bytes(4, "big")) + uelem(ID_SEEK_POS, target_pos)),
    )


def no_seekhead_mkv() -> bytes:
    """header + segment(info + tracks + cluster + chapters): stops at the Cluster."""
    segment = elem(ID_SEGMENT, segment_info() + tracks() + cluster() + chapters())
    return header() + segment


def seekhead_gaps_mkv() -> bytes:
    """header + segment(seekhead{Chapters}, cluster, chapters)."""
    dummy = elem(ID_CLUSTER, bytes(8192))
    info = segment_info()
    chapters_elem = chapters()
    target = 0
    for _ in range(4):
        seek_head = _seek_head(ID_CHAPTERS, target)
        next_target = len(seek_head) + len(dummy) + len(info)
        if next_target == target:
            break
        target = next_target
    segment = elem(ID_SEGMENT, seek_head + dummy + info + chapters_elem)
    return header() + segment


if __name__ == "__main__":
    for name, make in [
        ("sample.mkv", sample_mkv),
        ("no_seekhead.mkv", no_seekhead_mkv),
        ("seekhead_gaps.mkv", seekhead_gaps_mkv),
    ]:
        path = OUT / name
        path.write_bytes(make())
        print(f"{name}: {path.stat().st_size} bytes")
